// Build the CV PDF from the same data that drives the website.
//
//   data/*.json  ->  CV/cv/*.tex (generated)  ->  xelatex  ->  public/cv.pdf
//
// Run with:  npm run cv
//
// The .tex section files under CV/cv/ are OVERWRITTEN on every run — do not edit
// them by hand. To change the CV's *look*, edit CV/cv.tex or CV/resume.cls.
// To change the CV's *content*, edit the JSON files under data/.
//
// A section whose data is empty is written as an empty file, so it simply
// disappears from the PDF (no empty headings).

import { readFileSync, writeFileSync, copyFileSync, existsSync } from 'node:fs';
import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import { dirname, resolve } from 'node:path';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const DATA = (name) => resolve(ROOT, 'data', name);
const CV_DIR = resolve(ROOT, 'CV');
const SECTION = (name) => resolve(CV_DIR, 'cv', name);

const read = (p) => JSON.parse(readFileSync(p, 'utf8'));

const about = read(DATA('about.json'));
const education = read(DATA('education.json'));
const { publications } = read(DATA('publications.json'));
const teaching = read(DATA('teaching.json'));
const cv = read(DATA('cv.json'));

// --- LaTeX helpers ----------------------------------------------------------

/** Escape a plain string so it is safe to drop into LaTeX text. */
function tex(value) {
  return String(value ?? '')
    .replace(/\\/g, '\\textbackslash ')
    .replace(/([&%$#_])/g, '\\$1')
    .replace(/\{/g, '\\{')
    .replace(/\}/g, '\\}')
    .replace(/~/g, '\\textasciitilde ')
    .replace(/\^/g, '\\textasciicircum ');
}

/** Escape a URL for \href (only % and # need it there). */
const texUrl = (url) => String(url).replace(/([%#])/g, '\\$1');

/** Dates: escape, and turn "2024 - present" / "2022-2023" into en-dash ranges. */
const texDate = (d) => tex(d).replace(/\s*-\s*/g, '--');

const HEADER = '% AUTO-GENERATED by scripts/build-cv.mjs — do not edit by hand.\n';

const myName = about.name;

/** Bold the author entry that is me; escape everyone. */
function formatAuthors(authors = []) {
  return authors
    .map((a) =>
      a.toLowerCase().includes(myName.toLowerCase())
        ? `\\textbf{${tex(a)}}`
        : tex(a)
    )
    .join(', ');
}

/** One publication -> citation text (title links to the paper when we have a URL). */
function formatPublication(p) {
  const url = p.ssrn || p.url || p.pdf;
  const title = url
    ? `\\href{${texUrl(url)}}{\\emph{${tex(p.title)}}}`
    : `\\emph{${tex(p.title)}}`;
  const parts = [`${formatAuthors(p.authors)}.`, `${title}.`];
  if (p.venue) parts.push(`${tex(p.venue)}.`);
  if (p.year) parts.push(`${tex(p.year)}.`);
  if (p.note) parts.push(tex(p.note));
  if (p.highlight) parts.push(`\\textbf{${tex(p.highlight)}.}`);
  return parts.join(' ');
}

// --- resume.cls building blocks ---------------------------------------------

/** \begin{rSection}{title} ... \end{rSection}; '' when there is no body. */
const rSection = (title, body) =>
  body.trim() ? `\\begin{rSection}{${title}}\n\n${body.trim()}\n\n\\end{rSection}` : '';

/** An itemize list; '' when empty. */
const itemize = (items) =>
  items.length
    ? `\\begin{itemize}\n${items.map((i) => `  \\item ${i}`).join('\n')}\n\\end{itemize}`
    : '';

/** "{\bf left} \hfill {\em right}" — the template's entry heading line. */
const headline = (left, right) =>
  right ? `{\\bf ${left}} \\hfill {\\em ${right}}` : `{\\bf ${left}}`;

/** Text followed by a right-aligned italic date. */
const dated = (text, date) => (date ? `${text} \\hfill {\\em ${texDate(date)}}` : text);

/** A bold label followed by its bullet list (the template's "Projects" style). */
const labelled = (label, items) => (items.length ? `${headline(label)}\n${itemize(items)}` : '');

/** Group items by key, keeping first-seen order. */
function groupBy(items, key) {
  const groups = new Map();
  for (const it of items) {
    const k = key(it);
    if (!groups.has(k)) groups.set(k, []);
    groups.get(k).push(it);
  }
  return [...groups.entries()];
}

/** Join non-empty blocks with a blank line (a paragraph gap under parskip). */
const join = (...blocks) => blocks.filter(Boolean).join('\n\n');

const writeSection = (file, body) =>
  writeFileSync(SECTION(file), HEADER + (body ? body + '\n' : ''));

// --- Personal info (header) -------------------------------------------------
// Line 1: position · school · university.  Line 2: office · phone · email · web.
// A "\\" inside \address prints as the diamond separator.

const positionLine = [...String(about.cvPosition ?? '').split('·'), about.affiliation]
  .map((s) => s?.trim())
  .filter(Boolean)
  .map(tex)
  .join(' \\\\ ');
const contactLine = [
  about.office ? tex(about.office) : '',
  about.phone ? tex(about.phone) : '',
  about.email ? `\\href{mailto:${texUrl(about.email)}}{${tex(about.email)}}` : '',
  about.homepage
    ? `\\href{${texUrl(about.homepage)}}{${tex(about.homepage.replace(/^https?:\/\//, ''))}}`
    : '',
]
  .filter(Boolean)
  .join(' \\\\ ');

writeSection(
  '_personal.tex',
  [
    `\\name{${tex(about.name)}}`,
    positionLine ? `\\address{${positionLine}}` : '',
    contactLine ? `\\address{${contactLine}}` : '',
  ]
    .filter(Boolean)
    .join('\n')
);

// --- Education --------------------------------------------------------------

const eduEntries = education.map((e) => {
  const where = [e.institution, e.location].filter(Boolean).map(tex).join(', ');
  const lines = [headline(where, texDate(e.date)), tex(e.degree)];
  if (e.advisor) lines.push(`Advisor: Dr.~${tex(e.advisor)}`);
  const notes = itemize((e.notes ?? []).map(tex));
  return lines.join('\n\\\\ ') + (notes ? `\n${notes}` : '');
});
writeSection('education.tex', rSection('Education', join(...eduEntries)));

// --- Research interests -----------------------------------------------------

writeSection(
  'interests.tex',
  rSection(
    'Research Interests',
    // Ragged-right so a wrapped list doesn't get stretched word gaps, and
    // ~ keeps each multi-word interest on one line.
    (about.researchInterests?.en ?? []).length
      ? `{\\raggedright ${about.researchInterests.en
          .map((i) => tex(i).replace(/ /g, '~'))
          .join(', ')}\\par}`
      : ''
  )
);

// --- Professional experience ------------------------------------------------

const expEntries = cv.experience.map((x) => {
  const who = [x.role, x.organization].filter(Boolean).map(tex).join(', ');
  const head =
    headline(who, texDate(x.date)) + (x.title ? `\n\\\\ \\textit{${tex(x.title)}}` : '');
  const notes = itemize((x.notes ?? []).map(tex));
  return head + (notes ? `\n${notes}` : '');
});
writeSection('professional.tex', rSection('Professional Experience', join(...expEntries)));

// --- Publications (Published / In Review / In Preparation) ------------------

const pubsByStatus = (status) =>
  publications.filter((p) => p.status === status).map(formatPublication);
writeSection(
  'publications.tex',
  rSection(
    'Publications',
    join(
      labelled('Published', pubsByStatus('published')),
      labelled('In Review', pubsByStatus('in_review')),
      labelled('In Preparation', pubsByStatus('in_prep'))
    )
  )
);

// --- Awards, fellowships & grants -------------------------------------------

const awardItems = cv.awards.map((a) => {
  let text = `\\textbf{${tex(a.title)}}`;
  if (a.organization) text += `, ${tex(a.organization)}`;
  if (a.detail) text += ` (${tex(a.detail)})`;
  return dated(text, a.date);
});
writeSection('honors.tex', rSection('Awards, Fellowships \\& Grants', itemize(awardItems)));

// --- Presentations ----------------------------------------------------------
// Talks that share a title are grouped under it, one bullet per venue.

const talks = [
  ...cv.presentations.invited.map((t) => ({ ...t, invited: true })),
  ...cv.presentations.contributed,
];
const talkBlocks = groupBy(talks, (t) => t.title).map(([title, group]) =>
  labelled(
    tex(title),
    group.map((t) => {
      const where = [t.event, t.location].filter(Boolean).map(tex).join(', ');
      return dated(where + (t.invited ? ' (invited)' : ''), t.date);
    })
  )
);
writeSection('presentation.tex', rSection('Presentations', join(...talkBlocks)));

// --- Teaching ---------------------------------------------------------------

const roleLabel = { ta: 'Teaching Assistant', instructor: 'Instructor' };
const teachBlocks = groupBy(teaching, (c) => c.role).map(([role, courses]) =>
  labelled(
    tex(roleLabel[role] ?? role),
    courses.map((c) =>
      dated([c.course, c.location].filter(Boolean).map(tex).join(', '), c.semester)
    )
  )
);
writeSection('teaching.tex', rSection('Teaching Experience', join(...teachBlocks)));

// --- Mentoring --------------------------------------------------------------

const mentorItems = cv.mentoring.map((m) =>
  dated(
    [`\\textbf{${tex(m.name)}}`, tex(m.relationship), tex(m.location)]
      .filter(Boolean)
      .join(', '),
    m.date
  )
);
writeSection('mentoring.tex', rSection('Mentoring', itemize(mentorItems)));

// --- Service & professional development -------------------------------------

const serviceItems = cv.service.map((s) =>
  dated([s.role, s.organization, s.location].filter(Boolean).map(tex).join(', '), s.date)
);
const developmentItems = cv.development.map((d) =>
  dated([d.title, d.location].filter(Boolean).map(tex).join(', '), d.year)
);
const inlineList = (label, list) =>
  list.length ? `${headline(label)}\n\\\\ ${list.map(tex).join(', ')}` : '';

writeSection(
  'extracurricular.tex',
  rSection(
    'Service \\& Professional Development',
    join(
      labelled('Service and Outreach', serviceItems),
      labelled('Professional Development', developmentItems),
      inlineList('Peer Review', cv.peerReview),
      inlineList('Professional Memberships', cv.memberships)
    )
  )
);

console.log('✓ Generated CV/cv/*.tex from data/');

// --- Compile ----------------------------------------------------------------

// Single command string (not args array) so this works with shell:true on both
// platforms without Node's DEP0190 warning. All arguments are static.
const latexmk = spawnSync(
  'latexmk -xelatex -interaction=nonstopmode -halt-on-error cv.tex',
  {
    cwd: CV_DIR,
    stdio: 'inherit',
    shell: true,
  }
);

if (latexmk.status !== 0) {
  console.error('\n✗ latexmk failed. See log above (CV/cv.log).');
  process.exit(latexmk.status ?? 1);
}

const built = resolve(CV_DIR, 'cv.pdf');
if (!existsSync(built)) {
  console.error('✗ Expected CV/cv.pdf was not produced.');
  process.exit(1);
}
copyFileSync(built, resolve(ROOT, 'public', 'cv.pdf'));
console.log('✓ Wrote public/cv.pdf');
